    stk asegs m lo q -> (lo <= q - IVF_DEPTH) -> (GLOBALS_TOP <= lo) -> (q <= 2^47) -> (q mod 16 = 0) ->
    ssp_cells m canary -> mem_inv asegs m -> frm0 fc ->
    (65536 <= A) -> (A + zlength fmt <= STATIC_SPLIT) ->
